@js:
var config = {};
try {
  if (source.loginUi) {
    config = JSON.parse(source.loginUi);
  }
} catch(e) {}

var textToSpeak = "";
try {
  if (typeof speakText !== "undefined" && speakText !== null) {
    textToSpeak = speakText + "";
  }
} catch(e) {}

var normalizedText = Packages.java.text.Normalizer.normalize(textToSpeak, Packages.java.text.Normalizer.Form.NFC);
var cleanText = normalizedText
  .replace(/[\r\n\t]/g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/[^a-zA-Z0-9 àáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđÀÁẢÃẠĂẰẮẲẴẶÂẦẤẨẪẬÈÉẺẼẸÊỀẾỂỄỆÌÍỈĨỊÒÓỎÕỌÔỒỐỔỖỘƠỜỚỞỠỢÙÚỦŨỤƯỪỨỬỮỰỲÝỶỸỴĐ\.,!\?:;\"'_\s-]/g, ' ')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&apos;');

var safeText = cleanText.replace(/([.,!?:;])/g, '$1<break time="70ms"/>');

var rate = speakSpeed / 10.0;

var option = {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({
    input: { ssml: "<speak>" + safeText + "</speak>" },
    voice: { languageCode: "vi-VN", name: "vi-VN-Standard-A" },
    audioConfig: {
      audioEncoding: config.audioEncoding || "MP3",
      speakingRate: rate,
      pitch: typeof config.pitch !== "undefined" ? parseFloat(config.pitch) : 0.0,
      volumeGainDb: typeof config.volumeGain !== "undefined" ? parseFloat(config.volumeGain) : 0.0,
      effectsProfileId: config.effectsProfile ? [config.effectsProfile] : ["headphone-class-device"],
      sampleRateHertz: config.sampleRate ? parseInt(config.sampleRate) : 24000
    }
  })
};
"https://texttospeech.googleapis.com/v1/text:synthesize?key=AIzaSyA33f9cSqKdR-V4XNkZNZ_rh_dbT1VQJFo," + JSON.stringify(option);

loginCheckJs:
var responseString = result.body().string();
if (result.code() != 200) {
  throw new Error("HTTP " + result.code() + ": " + responseString.substring(0, 150));
}
var json = JSON.parse(responseString);
if (json.error) {
  throw new Error("API Err: " + JSON.stringify(json.error).substring(0, 150));
}
if (!json.audioContent) {
  throw new Error("No audioContent");
}
var audioBytes = Packages.android.util.Base64.decode(json.audioContent, 0);
var mediaType = Packages.okhttp3.MediaType.parse("audio/mpeg");
var responseBody;
try {
  responseBody = Packages.okhttp3.ResponseBody.create(audioBytes, mediaType);
} catch (e) {
  responseBody = Packages.okhttp3.ResponseBody.create(mediaType, audioBytes);
}
result.newBuilder().body(responseBody).header("Content-Type", "audio/mpeg").build();

